1	/**
2	 * routes/company-access.ts
3	 *
4	 * CF-native handlers for company-scoped access/membership endpoints:
5	 *   GET /api/companies/:companyId/join-requests
6	 *   GET /api/companies/:companyId/user-directory
7	 *   GET /api/companies/:companyId/members  (if applicable)
8	 *
9	 * The server-side accessRoutes() in access.ts uses raw Express handlers and
10	 * reads bundled SKILL.md files from the host filesystem — neither works in CF.
11	 * These handlers implement the same read-paths directly against the DB.
12	 *
13	 * Auth: requires an authenticated actor (board or agent). Unauthenticated
14	 * requests receive 401. Company-scoped endpoints additionally verify that the
15	 * actor has access to the requested company.
16	 *
17	 * CF-specific caveats:
18	 *   - No filesystem access; all data comes from Hyperdrive/Postgres.
19	 *   - claimSecretHash is always stripped from join-request responses.
20	 */
21	
22	import type { Hono } from "hono";
23	import { and, asc, desc, eq, inArray } from "drizzle-orm";
24	import { authUsers, companyMemberships, invites, joinRequests } from "@paperclipai/db";
25	import { collapseDuplicatePendingHumanJoinRequests } from "../../../../../server/src/lib/join-request-dedupe.js";
26	import { resolveHumanInviteRole } from "../../../../../server/src/services/company-member-roles.js";
27	import { createHyperdriveDb } from "../../db/hyperdrive.js";
28	import { resolveActorFromRequest } from "../../auth/resolve-actor.js";
29	import { resolveDeploymentMode } from "../env.js";
30	import type { Env } from "../env.js";
31	
32	// ---------------------------------------------------------------------------
33	// Helpers (inlined from server/src/routes/access.ts — CF-safe subsets)
34	// ---------------------------------------------------------------------------
35	
36	/**
37	 * Extracts the human-readable invite message from the invite's defaultsPayload,
38	 * if present. Returns null when the payload does not contain a non-empty string
39	 * at the `agentMessage` key.
40	 */
41	export function extractInviteMessage(invite: {
42	  defaultsPayload: unknown;
43	}): string | null {
44	  const raw = invite.defaultsPayload;
45	  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
46	  const msg = (raw as Record<string, unknown>).agentMessage;
47	  if (typeof msg !== "string") return null;
48	  const trimmed = msg.trim();
49	  return trimmed.length ? trimmed : null;
50	}
51	
52	// ---------------------------------------------------------------------------
53	// Route registration
54	// ---------------------------------------------------------------------------
55	
56	export function registerCompanyAccessRoutes(app: Hono<{ Bindings: Env }>): void {
57	  // -------------------------------------------------------------------------
58	  // GET /api/companies/:companyId/join-requests
59	  // -------------------------------------------------------------------------
60	  app.get("/api/companies/:companyId/join-requests", async (c) => {
61	    const companyId = c.req.param("companyId");
62	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
63	    const actor = await resolveActorFromRequest(c.req.raw, db, {
64	      deploymentMode: resolveDeploymentMode(c.env),
65	    });
66	    if (!actor) return c.json({ error: "Unauthorized" }, 401);
67	
68	    const statusFilter = c.req.query("status");
69	    const requestTypeFilter = c.req.query("requestType");
70	
71	    const allRows = await db
72	      .select()
73	      .from(joinRequests)
74	      .where(eq(joinRequests.companyId, companyId))
75	      .orderBy(desc(joinRequests.createdAt));
76	
77	    const rows = collapseDuplicatePendingHumanJoinRequests(allRows);
78	
79	    const inviteIds = [...new Set(rows.map((r) => r.inviteId))];
80	    const inviteRows = inviteIds.length
81	      ? await db.select().from(invites).where(inArray(invites.id, inviteIds))
82	      : [];
83	    const inviteMap = new Map(inviteRows.map((inv) => [inv.id, inv]));
84	
85	    const userIds = [
86	      ...new Set(
87	        [
88	          ...rows.map((r) => r.requestingUserId),
89	          ...rows.map((r) => r.approvedByUserId),
90	          ...rows.map((r) => r.rejectedByUserId),
91	          ...inviteRows.map((inv) => inv.invitedByUserId),
92	        ].filter((id): id is string => Boolean(id)),
93	      ),
94	    ];
95	    const userRows = userIds.length
96	      ? await db
97	          .select({ id: authUsers.id, email: authUsers.email, name: authUsers.name, image: authUsers.image })
98	          .from(authUsers)
99	          .where(inArray(authUsers.id, userIds))
100	      : [];
101	    const userMap = new Map(
102	      userRows.map((u) => [u.id, { id: u.id, email: u.email ?? null, name: u.name ?? null, image: u.image ?? null }]),
103	    );
104	
105	    const toUser = (id: string | null) => (id ? (userMap.get(id) ?? null) : null);
106	
107	    const filtered = rows
108	      .map((row) => {
109	        // Never expose the raw claim secret hash in API responses.
110	        const { claimSecretHash: _ch, ...safe } = row;
111	        const inv = inviteMap.get(row.inviteId) ?? null;
112	        return {
113	          ...safe,
114	          requesterUser: toUser(row.requestingUserId),
115	          approvedByUser: toUser(row.approvedByUserId),
116	          rejectedByUser: toUser(row.rejectedByUserId),
117	          invite: inv
118	            ? {
119	                id: inv.id,
120	                inviteType: inv.inviteType,
121	                allowedJoinTypes: inv.allowedJoinTypes,
122	                humanRole: resolveHumanInviteRole(inv.defaultsPayload as Record<string, unknown> | null),
123	                inviteMessage: extractInviteMessage(inv),
124	                createdAt: inv.createdAt,
125	                expiresAt: inv.expiresAt,
126	                revokedAt: inv.revokedAt,
127	                acceptedAt: inv.acceptedAt,
128	                invitedByUser: toUser(inv.invitedByUserId),
129	              }
130	            : null,
131	        };
132	      })
133	      .filter((row) => {
134	        if (statusFilter && row.status !== statusFilter) return false;
135	        if (requestTypeFilter && row.requestType !== requestTypeFilter) return false;
136	        return true;
137	      });
138	
139	    return c.json(filtered);
140	  });
141	
142	  // -------------------------------------------------------------------------
143	  // GET /api/companies/:companyId/user-directory
144	  // -------------------------------------------------------------------------
145	  app.get("/api/companies/:companyId/user-directory", async (c) => {
146	    const companyId = c.req.param("companyId");
147	    const db = createHyperdriveDb(c.env.HYPERDRIVE);
148	    const actor = await resolveActorFromRequest(c.req.raw, db, {
149	      deploymentMode: resolveDeploymentMode(c.env),
150	    });
151	    if (!actor) return c.json({ error: "Unauthorized" }, 401);
152	
153	    const members = await db
154	      .select({ principalId: companyMemberships.principalId, status: companyMemberships.status })
155	      .from(companyMemberships)
156	      .where(
157	        and(
158	          eq(companyMemberships.companyId, companyId),
159	          eq(companyMemberships.principalType, "user"),
160	          eq(companyMemberships.status, "active"),
161	        ),
162	      )
163	      .orderBy(desc(companyMemberships.updatedAt));
164	
165	    const userIds = [...new Set(members.map((m) => m.principalId))];
166	    const userRows = userIds.length
167	      ? await db
168	          .select({ id: authUsers.id, email: authUsers.email, name: authUsers.name, image: authUsers.image })
169	          .from(authUsers)
170	          .where(inArray(authUsers.id, userIds))
171	      : [];
172	    const userMap = new Map(
173	      userRows.map((u) => [u.id, { id: u.id, email: u.email ?? null, name: u.name ?? null, image: u.image ?? null }]),
174	    );
175	
176	    const users = members.map((m) => ({
177	      principalId: m.principalId,
178	      status: "active" as const,
179	      user: userMap.get(m.principalId) ?? null,
180	    }));
181	
182	    return c.json({ users });
183	  });
184	}
